            '}' => Some(Token {t_type: TokenType::BraceClose, ..Default::default()}),
            _   => Some(Token {t_type: TokenType::Unknown, ..Default::default()})
        };

        if tok.is_some() {
            tokens.push(tok.unwrap());
        }
    }

    return tokens;
}

