                if !current.is_empty() {
                    tokens.push(create_token(&current));
                    current.clear();
                }
            }
            '+' => {
                if !current.is_empty() {
                    tokens.push(create_token(&current));
                    current.clear();
                }
                tokens.push(Token { t_type: TokenType::Add, t_val: String::from("+") });
            }
            '-' => {
                if !current.is_empty() {
                    tokens.push(create_token(&current));
                    current.clear();
                }
                tokens.push(Token { t_type: TokenType::Subtract, t_val: String::from("-") });
            }
            '*' => {
                if !current.is_empty() {
                    tokens.push(create_token(&current));
                    current.clear();
                }
                tokens.push(Token { t_type: TokenType::Multiply, t_val: String::from("*") });
            }
            '/' => {
                if !current.is_empty() {
