    pub fn select_where_possible(&mut self, infcx: &InferCtxt<'_, 'tcx>) -> Result<(), FulfillmentError<'tcx>> {
        let mut selection_errors = Vec::new();
        let mut ambiguous_obligations = Vec::new();

        for obligation in self.predicates.drain(..) {
            match infcx.select(obligation) {
                Ok(_) => {},
                Err(err) => {
                    selection_errors.push(err);
                    ambiguous_obligations.push(obligation);
                }
            }
        }

        self.predicates.extend(ambiguous_obligations);
        if !selection_errors.is_empty() {
            return Err(FulfillmentError::SelectionErrors(selection_errors));
        }

        Ok(())
    }
}

