    pub fn register_predicate_obligation(&mut self,
                                         infcx: &InferCtxt<'_, 'tcx>,
                                         obligation: PredicateObligation<'tcx>) {
        if self.duplicate_set.set.insert(obligation.predicate.clone()) {
            self.predicates.push(obligation);
        }
    }

    pub fn select_where_possible(&mut self, infcx: &InferCtxt<'_, 'tcx>) -> bool {
        let mut selected = false;
        while self.attempted_mark < self.predicates.len() {
            let obligation = &mut self.predicates[self.attempted_mark];
            match infcx.select(&obligation) {
                Ok(_) => {
                    selected = true;
                    self.attempted_mark += 1;
                }
                Err(_) => {
                    self.attempted_mark += 1;
                }
            }
        }
        selected
    }

    pub fn report_errors(&self, infcx: &InferCtxt<'_, 'tcx>) {
        for obligation in &self.predicates {
            if let Err(ref err) = obligation {
                infcx.report_error(err);
            }
        }
    }
}

