fn diff_left(a: serde_json::map::Keys, b: &Vec<String>) -> Vec<String> {
    let mut diff = Vec::<String>::new();
    'outer: for a_item in a {
        for b_item in b {
            if a_item == b_item {
                continue 'outer;
            }
        }
        diff.push(a_item.clone());
    }
    diff
}

