      match from_str::<uint>(args[1].as_slice()){
        Some(x) => width = x,
        None    => fail!("Argument supplied is not a positive number")
      };
    } else {
      print!("Use default value 50 as width")
    }
    if args.len() > 2 {
      match from_str::<uint>(args[2].as_slice()){
        Some(x) => height = x,
