pub fn sent_mean(word_total: &f32, sentences: &Vec<&str>) -> f32 {
	let sent_mean: f32;
	let sent_total;

	sent_total = sentences.len() as f32;

	let total_sent = sent_total as f32;

	sent_mean = word_total / total_sent;

	return sent_mean;
}

