    fn create_socket(id: &ConnectionId) -> io::Result<UdpSocket> {
        let addr = SocketAddr::new(Ipv4Addr::new(0, 0, 0, 0).into(), id.port());
        let socket = UdpSocket::bind(&addr)?;
        cx_info!(target: TAG, id, "Socket created at {:?}", addr);
        Ok(socket)
    }

    fn on_ready(&mut self, selector: &mut Selector, event: Event) {
        if self.closed {
            return;
        }

        if event.readiness().is_readable() {
            self.read_from_network(selector).unwrap_or_else(|e| {
                cx_error!(target: TAG, "Error reading from network: {}", e);
                self.close();
            });
        }

        if event.readiness().is_writable() {
            self.write_to_network().unwrap_or_else(|e| {
                cx_error!(target: TAG, "Error writing to network: {}", e);
                self.close();
            });
        }

        self.check_idle_timeout();
    }

