pub fn execute_script(script: &str) -> Result<(), String> {
    // Initialize the JavaScript engine
    let context = js::create_context().map_err(|e| e.to_string())?;

    // Evaluate the script
    match js::evaluate(&context, script) {
        Ok(result) => {
            // Handle the result of the script execution
            println!("Script executed successfully: {:?}", result);
            Ok(())
        },
        Err(e) => {
            // Handle any errors that occurred during execution
            Err(format!("Script execution failed: {}", e))
        }
    }
}

