pub fn execute_script(script: &str) -> Result<(), String> {
    // Parse the script
    let parsed_script = match js::parse(script) {
        Ok(parsed) => parsed,
        Err(e) => return Err(format!("Failed to parse script: {}", e)),
    };

    // Create a new execution context
    let context = js::create_execution_context();

    // Execute the script within the context
    match js::execute_in_context(&context, &parsed_script) {
        Ok(_) => Ok(()),
        Err(e) => Err(format!("Execution error: {}", e)),
    }
}

