        let packet = input.next();

        let mut s = Simulator {
            input,
            current_time: Time(0),
            switch,
            next_packet: packet,
        };
        if s.next_packet.is_some() {
            s.switch.add_packet(&s.next_packet.unwrap());
        }

        s
    }

