            self.speed_time_left = self.speed_time;
            self.rest_time_left = self.rest_time;
        }

        if self.rest_time_left < 0 {
            self.rest_time_left = 0;
        }
    }

    fn award_points(&mut self) {
        self.points += 1;
    }
}

