/// use std::f32::consts::PI;

/// Converts the Euler angles to a quaternion representation.
pub fn to_quaternion(&self) -> Quaternion<f32> {
    let (cx, cy, cz) = (self.x.cos(), self.y.cos(), self.z.cos());
    let (sx, sy, sz) = (self.x.sin(), self.y.sin(), self.z.sin());

    let qw = cx * cy * cz + sx * sy * sz;
    let qx = sx * cy * cz - cx * sy * sz;
    let qy = cx * sy * cz + sx * cy * sz;
    let qz = cx * cy * sz - sx * sy * cz;

    Quaternion::new(qw, qx, qy, qz)
}

