impl<A: BaseFloat> Euler<A> {
    pub fn to_quaternion(&self) -> Quaternion<A> {
        let half_x = self.x / cast(2.0).unwrap();
        let half_y = self.y / cast(2.0).unwrap();
        let half_z = self.z / cast(2.0).unwrap();

        let cy = half_z.cos();
        let sy = half_z.sin();
        let cp = half_y.cos();
        let sp = half_y.sin();
        let cr = half_x.cos();
        let sr = half_x.sin();

        Quaternion {
            w: cr * cp * cy + sr * sp * sy,
            x: sr * cp * cy - cr * sp * sy,
            y: cr * sp * cy + sr * cp * sy,
            z: cr * cp * sy - sr * sp * cy,
        }
    }
}

