pub fn io_handler(client: Arc<Client>, exit_signal: Arc<AtomicBool>) {
    // Set up necessary configurations and initialize the I/O handler
    let listener = TcpListener::bind("127.0.0.1:8080").expect("Failed to bind to address");

    for stream in listener.incoming() {
        match stream {
            Ok(mut socket) => {
                let client_clone = Arc::clone(&client);
                let exit_signal_clone = Arc::clone(&exit_signal);

                // Spawn a new thread to handle the incoming connection
                std::thread::spawn(move || {
                    handle_connection(socket, client_clone, exit_signal_clone);
                });
            }
            Err(e) => {
                eprintln!("Connection failed: {}", e);
            }
        }

        if exit_signal.load(Ordering::Relaxed) {
            break;
        }
    }
}

