        // z = e = y - X * theta
        z[..] = y - X * theta;

        // theta = theta + alpha / m * x' * e
        *theta += alpha * X.t() * &*z / m;

        let J = cost(X, y, theta, z);

        debug!("i: {}, J: {}, theta: {:?}", i, J, theta);

        // Stop condition: `cost` reduced by less than `TOL`% in last iteration
        if (J - last_J).abs() / J.max(last_J) < TOL {
            return i
        }

        last_J = J;
    }

    max_niters
}

