        let mut nrows = 1;
        while let Some(line) = lines.next() {
            let line = try!(line);

            for number in line.split_whitespace() {
                v.push(number.parse().unwrap());
            }

            nrows += 1;
        }

        unsafe {
            Ok(Mat::from_raw_parts(v.into_boxed_slice(), (ncols, nrows)).t())
        }
    }

    load(path.as_ref())
}

