// Function to register a window class
pub fn register_window_class(class_name: &str, wnd_proc: WNDPROC) -> BOOL {
    let mut wc: WNDCLASSW = unsafe { std::mem::zeroed() };
    wc.lpfnWndProc = wnd_proc;
    wc.lpszClassName = to_wstring(class_name).as_ptr();
    wc.hInstance = unsafe { GetModuleHandleW(std::ptr::null()) };
    wc.hCursor = unsafe { LoadCursorW(std::ptr::null_mut(), IDC_ARROW) };
    wc.hbrBackground = (COLOR_WINDOW + 1) as HBRUSH;

    let result = unsafe { RegisterClassW(&wc) };
    if result == 0 {
        return 0; // Registration failed
    }
    return 1; // Registration successful
}

// Helper function to convert Rust string to wide string
fn to_wstring(string: &str) -> Vec<wchar_t> {
    let wide_string: Vec<wchar_t> = string.encode_utf16().chain(std::iter::once(0)).collect();
    wide_string
}

